window.kbPageData["views/entry/k-8afb79af6cae9a69"] = {"key":"entry/k-8afb79af6cae9a69","state":{"route":"entry/k-8afb79af6cae9a69"},"node":{"id":"k-8afb79af6cae9a69","mode":"k","title":"专有车位安装充电桩的物业协助义务","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["物业服务人对业主在专有车位合规安装充电桩负有必要协助义务"],"qs":["江苏 2023 B类 行测#10"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"业主为自用车辆依法在专有车位安装充电桩，属于对车位的合理使用。物业服务人应当提供必要协助，包括按报装要求出具施工同意证明，并配合现场勘查和施工。","review":{"definition":"业主为自用车辆依法在专有车位安装充电桩，属于对车位的合理使用。物业服务人应当提供必要协助，包括按报装要求出具施工同意证明，并配合现场勘查和施工。","explanation":"张某的地下车位归其专有，供电部门已勘查认为可以安装，物业公司应配合提供报装所需证明，D项正确。法院在类似案件中将这类协助纳入物业服务合同的履行范围。施工仍须符合用电、消防等要求，物业盖章是报装环节，题中也没有须另行办理行政审批的事实依据。","references":[{"source":"web-13f6e2b627138384","location":"裁判理由第二点","quote":"仅是安装充电桩的一个环节"},{"source":"web-59da6c70dc332f9b","location":"“物业公司应该配合协助业主”","quote":"亦为物业服务应有之义"}],"evidence":"但告知他需提供物业公司同意施工的证明材料","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#10":{"paper":"江苏 2023 B类 行测","n":10,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",2],"asrc":["b08f2713d73015eac675.pdf",4],"card":"8e66ce0a4bb20d071224c459","links":[{"id":"k-8afb79af6cae9a69","role":"直接考查","why":"物业服务合同义务是判断物业公司应如何配合施工的依据。"}]}},"terms":{},"references":{"web-13f6e2b627138384":{"name":"最高人民法院入库参考案例《聂某诉碧某生活服务集团股份有限公司东莞分公司等物业服务合同纠纷案》","url":"https://www.court.gov.cn/zixun/xiangqing/449251.html"},"web-59da6c70dc332f9b":{"name":"南通市崇川区人民法院《充电桩进小区难过“物业关”？》","url":"https://www.jsfy.gov.cn/article/94181.html"}},"topics":[],"units":{"k-8afb79af6cae9a69":[["江苏 2023 B类 行测#10"]]}};
